from svk.data._stormsurgebarrier import StormSurgeBarrier
from svk.data._icon import Icon, PathIconElement, RectIconElement
from svk.data._timeframe import TimeFrame

accent_fill = "#a7a7a7"


class IconProvider:
    @staticmethod
    def create_icon(barrier: StormSurgeBarrier) -> Icon | None:
        match barrier:
            case StormSurgeBarrier.EasternScheldtBarrier:
                return IconProvider.create_eastern_scheldt_barrier_icon()
            case StormSurgeBarrier.HaringvlietBarrier:
                return IconProvider.create_haringvliet_sluices_icon()
            case StormSurgeBarrier.MaeslantBarrier:
                return IconProvider.create_maeslant_barrier_icon()
            case StormSurgeBarrier.HollandseIJsselBarrier:
                return IconProvider.create_hollandse_ijssel_barrier_icon()
            case StormSurgeBarrier.Ramspol:
                return IconProvider.create_ramspol_icon()
            case StormSurgeBarrier.HartelBarrier:
                return IconProvider.create_hartel_barrier_icon()
            case StormSurgeBarrier.All:
                return IconProvider.create_6svk_icon()
            case StormSurgeBarrier.SluicePanheel:
                return IconProvider.create_sluice_panheel_icon()
            case _:
                return None

