    @staticmethod
    def create_time_frame_icon(time_frame: TimeFrame) -> Icon | None:
        match time_frame:
            case TimeFrame.Now:
                return IconProvider.create_time_frame_now_icon()
            case TimeFrame.NearFuture:
                return IconProvider.create_time_frame_near_future_icon()
            case TimeFrame.Future:
                return IconProvider.create_time_frame_future_icon()

        return None
